import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, interpolateColors } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type MindfulPathProps = Record<string, any>;

const MindfulPath: React.FC<MindfulPathProps> = ({
  backgroundColor = "#f0f4f8", // Cold neutral background
  transparentBackground = false,
  durationInSeconds = 10,
  mainLineColor = "#2d3436", // Harsh dark outline
  healthyPathColor = "#e17055", // Vibrant warm heart color (Initial)
  fadedPathColor = "#b2bec3", // Cold grey (Declined)
  strokeWidth = 2,
  animationSpeed = 1,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Dimensions
  const minDim = Math.min(width, height);
  const centerX = width / 2;
  const centerY = height / 2;
  const baseRadius = minDim * 0.3;

  // Animation drivers
  const entrance = spring({
    frame,
    fps,
    config: { damping: 100, stiffness: 20 },
  });

  // Timeline Progress: 0 (Start) -> 1 (End of decline)
  const durationFrames = durationInSeconds * fps;
  const progress = interpolate(frame, [0, durationFrames], [0, 1], {
    extrapolateRight: "clamp",
  });

  // 1. Breathing becomes shallow over time
  // Amplitude decreases from 0.05 to 0.005
  const breathAmplitude = interpolate(progress, [0, 1], [0.05, 0.005]);
  const breathCycle = (frame / fps) * animationSpeed;
  const breathScale = 1 + Math.sin(breathCycle) * breathAmplitude;

  // 2. The Core "Self" shrinks
  const coreScale = interpolate(progress, [0, 1], [1, 0.4]);

  // 3. Colors shift from Warm (Love) to Cold (Indifference/Sickness)
  const currentCoreColor = interpolateColors(
    progress,
    [0, 1],
    [healthyPathColor, fadedPathColor]
  );
  
  const currentGlowColor = interpolateColors(
    progress,
    [0, 1],
    [healthyPathColor, "#000000"] // Glow turns into shadow
  );

  // 4. Glow fades and becomes a shadow
  const glowOpacity = interpolate(progress, [0, 0.8], [0.6, 0]);
  const shadowOpacity = interpolate(progress, [0.5, 1], [0, 0.5]);

  // 5. Constriction Ring (External Pressure/Self-Criticism)
  // Appears and constricts the core
  const constrictionScale = interpolate(progress, [0, 1], [1.5, 0.5]);
  const constrictionOpacity = interpolate(progress, [0, 0.5, 1], [0, 0.8, 1]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ overflow: "visible" }}
      >
        <defs>
          <filter id="softBlur">
            <feGaussianBlur stdDeviation="20" result="blur" />
          </filter>
          <filter id="glowBlur">
            <feGaussianBlur stdDeviation="30" result="blur" />
          </filter>
        </defs>

        <g
          style={{
            transformBox: "fill-box",
            transformOrigin: "center center",
            transform: `scale(${entrance})`,
          }}
        >
          {/* Main Container Group */}
          <g
            style={{
              transformBox: "fill-box",
              transformOrigin: "center center",
              transform: `translate(${centerX}px, ${centerY}px)`,
            }}
          >
            {/* 1. Fading Warmth (Back Glow) */}
            <circle
              r={baseRadius * 1.2}
              fill={currentGlowColor}
              opacity={glowOpacity}
              filter="url(#glowBlur)"
            />

            {/* 2. Encroaching Shadow (Depression/Decline) */}
            <circle
              r={baseRadius * 1.2}
              fill="#000000"
              opacity={shadowOpacity}
              filter="url(#softBlur)"
              style={{
                transform: `scale(${constrictionScale})`, // Moves inward
              }}
            />

            {/* 3. The Shrinking Self (Core) */}
            <g
                style={{
                    transform: `scale(${breathScale})`, // Breathing
                }}
            >
                {/* Core Shape */}
                <circle
                  r={baseRadius}
                  fill={currentCoreColor}
                  style={{
                    transform: `scale(${coreScale})`, // Shrinking permanently
                    transformBox: "fill-box",
                    transformOrigin: "center center",
                  }}
                />
            </g>

            {/* 4. Constriction Lines (Barriers) */}
            <circle
              r={baseRadius}
              fill="none"
              stroke={mainLineColor}
              strokeWidth={strokeWidth}
              opacity={constrictionOpacity}
              style={{
                transform: `scale(${constrictionScale})`,
                transformBox: "fill-box",
                transformOrigin: "center center",
              }}
            />
          </g>
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default MindfulPath;